import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

class FixedWindowRateLimiter {

    private final int limit;
    private final long windowSizeMillis;
    private final ConcurrentHashMap<String, WindowCounter> counters = new ConcurrentHashMap<>();

    FixedWindowRateLimiter(int limit, long windowSizeMillis) {
        this.limit = limit;
        this.windowSizeMillis = windowSizeMillis;
    }

    boolean allow(String key) {
        long now = System.currentTimeMillis();
        long windowStart = (now / windowSizeMillis) * windowSizeMillis; // floor to the window boundary

        WindowCounter counter = counters.compute(key, (k, existing) -> {
            if (existing == null || existing.windowStart != windowStart) {
                // either the first request for this key, or the clock has rolled into a
                // new window, either way the count restarts at zero from here
                return new WindowCounter(windowStart);
            }
            return existing;
        });

        return counter.count.incrementAndGet() <= limit;
    }

    private static class WindowCounter {
        final long windowStart;
        final AtomicInteger count = new AtomicInteger(0);

        WindowCounter(long windowStart) {
            this.windowStart = windowStart;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        FixedWindowRateLimiter limiter = new FixedWindowRateLimiter(5, 1000);
        for (int i = 0; i < 7; i++) {
            System.out.println("request " + i + " allowed=" + limiter.allow("user:42"));
        }
    }
}

