import java.util.concurrent.ConcurrentHashMap;

class TokenBucketRateLimiter {

    private final double capacity;
    private final double refillTokensPerMs;
    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    TokenBucketRateLimiter(double capacity, double refillTokensPerSecond) {
        this.capacity = capacity;
        this.refillTokensPerMs = refillTokensPerSecond / 1000.0;
    }

    synchronized boolean allow(String key) {
        long now = System.currentTimeMillis();
        Bucket bucket = buckets.computeIfAbsent(key, k -> new Bucket(capacity, now));

        // top up tokens for however much time passed since the last check, capped at
        // capacity so idle time cannot bank an unlimited amount of future credit
        double elapsedMs = now - bucket.lastRefillTimestamp;
        bucket.tokens = Math.min(capacity, bucket.tokens + elapsedMs * refillTokensPerMs);
        bucket.lastRefillTimestamp = now;

        if (bucket.tokens >= 1.0) {
            bucket.tokens -= 1.0;
            return true;
        }
        return false;
    }

    private static class Bucket {
        double tokens;
        long lastRefillTimestamp;

        Bucket(double initialTokens, long now) {
            this.tokens = initialTokens;
            this.lastRefillTimestamp = now;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        // capacity 5, refill 1 token per second: allows an initial burst of 5, then throttles
        TokenBucketRateLimiter limiter = new TokenBucketRateLimiter(5, 1.0);
        for (int i = 0; i < 7; i++) {
            System.out.println("burst request " + i + " allowed=" + limiter.allow("user:42"));
        }
    }
}

