import java.util.concurrent.ConcurrentHashMap;

class SlidingWindowCounterRateLimiter {

    private final int limit;
    private final long windowSizeMillis;
    private final ConcurrentHashMap<String, TwoWindowState> state = new ConcurrentHashMap<>();

    SlidingWindowCounterRateLimiter(int limit, long windowSizeMillis) {
        this.limit = limit;
        this.windowSizeMillis = windowSizeMillis;
    }

    synchronized boolean allow(String key) {
        long now = System.currentTimeMillis();
        long currentWindowStart = (now / windowSizeMillis) * windowSizeMillis;

        TwoWindowState s = state.computeIfAbsent(key, k -> new TwoWindowState(currentWindowStart));

        if (s.currentWindowStart != currentWindowStart) {
            // the window rolled over: what used to be "current" becomes "previous",
            // and only if it was the very last window, otherwise it is too old to count at all
            long windowsElapsed = (currentWindowStart - s.currentWindowStart) / windowSizeMillis;
            s.previousCount = windowsElapsed == 1 ? s.currentCount : 0;
            s.currentCount = 0;
            s.currentWindowStart = currentWindowStart;
        }

        double elapsedFraction = (now - currentWindowStart) / (double) windowSizeMillis;
        double weightOfPrevious = 1.0 - elapsedFraction;

        // the weighted average estimate: most of the previous window still counts
        // right after a rollover, and less of it counts the further in we get
        double estimatedCount = s.currentCount + s.previousCount * weightOfPrevious;

        if (estimatedCount + 1 > limit) {
            return false;
        }
        s.currentCount++;
        return true;
    }

    private static class TwoWindowState {
        long currentWindowStart;
        int currentCount = 0;
        int previousCount = 0;

        TwoWindowState(long currentWindowStart) {
            this.currentWindowStart = currentWindowStart;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        SlidingWindowCounterRateLimiter limiter = new SlidingWindowCounterRateLimiter(5, 1000);
        for (int i = 0; i < 7; i++) {
            System.out.println("request " + i + " allowed=" + limiter.allow("user:42"));
        }
    }
}

