import java.util.concurrent.ConcurrentHashMap;

class RedisAtomicRateLimiter {

    // The actual Lua script a production system loads into Redis and invokes with
    // EVALSHA. Redis executes every script on a single thread, which is what makes
    // the read, compare, and increment below atomic across every calling instance.
    static final String CHECK_AND_INCREMENT_SCRIPT =
        "local current = tonumber(redis.call('GET', KEYS[1]) or '0')\n" +
        "if current + 1 > tonumber(ARGV[1]) then\n" +
        "  return 0\n" +
        "else\n" +
        "  redis.call('INCR', KEYS[1])\n" +
        "  if current == 0 then\n" +
        "    redis.call('EXPIRE', KEYS[1], ARGV[2])\n" +
        "  end\n" +
        "  return 1\n" +
        "end";

    // A tiny in-process stand-in for a real Redis client. The synchronized method
    // below mirrors the atomicity a real EVALSHA call gets from Redis itself.
