class RateLimitKeyResolver {

    enum KeyStrategy { PER_USER, PER_IP, PER_API_KEY, PER_ENDPOINT, USER_AND_ENDPOINT }

    static class RequestContext {
        final String userId;
        final String clientIp;
        final String apiKey;
        final String endpointPath;

        RequestContext(String userId, String clientIp, String apiKey, String endpointPath) {
            this.userId = userId;
            this.clientIp = clientIp;
            this.apiKey = apiKey;
            this.endpointPath = endpointPath;
        }
    }

    // combines whichever dimensions a given policy cares about into one stable key,
    // the same logical request always hashes to the same Redis key
    String resolve(RequestContext ctx, KeyStrategy strategy) {
        switch (strategy) {
            case PER_USER:
                return "rl:user:" + ctx.userId;
            case PER_IP:
                return "rl:ip:" + ctx.clientIp;
            case PER_API_KEY:
                return "rl:apikey:" + ctx.apiKey;
            case PER_ENDPOINT:
                return "rl:endpoint:" + ctx.endpointPath;
            case USER_AND_ENDPOINT:
                // a tighter, endpoint specific budget layered on top of a broader one
                return "rl:user:" + ctx.userId + ":endpoint:" + ctx.endpointPath;
            default:
                throw new IllegalArgumentException("Unknown key strategy: " + strategy);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        RateLimitKeyResolver resolver = new RateLimitKeyResolver();
        RateLimitKeyResolver.RequestContext ctx =
            new RateLimitKeyResolver.RequestContext("42", "203.0.113.7", "abcd1234", "/api/v1/search");
        System.out.println(resolver.resolve(ctx, RateLimitKeyResolver.KeyStrategy.PER_USER));
        System.out.println(resolver.resolve(ctx, RateLimitKeyResolver.KeyStrategy.USER_AND_ENDPOINT));
    }
}

